(2953651, 414681, 34938, '<td valign="top">this is OK...not sure I really like the edit path you have chosen for this image</td>', 'this is OK...not sure I really like the edit path you have chosen for this image', '2006-10-23 08:28:37.000000', NULL, 1),
(2953657, 414423, 34938, '<td valign="top">great vantage point...thanks for the quirky title</td>', 'great vantage point...thanks for the quirky title', '2006-10-23 08:33:36.000000', NULL, 1),
(2953658, 415665, 48228, '<td valign="top">Classical......</td>', 'Classical......', '2006-10-23 08:33:43.000000', NULL, 1),
(2953659, 415456, 34938, '<td valign="top">would have been better if it was there ;-)</td>', 'would have been better if it was there ;-)', '2006-10-23 08:34:28.000000', NULL, 1),
(2953670, 415193, 31443, '<td valign="top">Ahhh, you''re going to get slaughtered for the date showing :( the idea is quite good but it does show a toy train and that won''t go all too well down with voters...welcome to DPC, your score is going to be low but don''t loose interest, there''s always the next challenge..</td>', 'Ahhh, you''re going to get slaughtered for the date showing :( the idea is quite good but it does show a toy train and that won''t go all too well down with voters...welcome to DPC, your score is going to be low but don''t loose interest, there''s always the next challenge..', '2006-10-23 08:39:23.000000', NULL, 1),
(2953675, 415424, 31443, '<td valign="top">Nicely composed, I like..</td>', 'Nicely composed, I like..', '2006-10-23 08:42:22.000000', NULL, 1),
(2953688, 415443, 48228, '<td valign="top">Very dramatic....very modern.... A stromg grahpic image that speeks volumns to the viewer.....<br/>I really hope you do well with this one, and it definately gets top votes from me.....</td>', 'Very dramatic....very modern.... A stromg grahpic image that speeks volumns to the viewer.....I really hope you do well with this one, and it definately gets top votes from me.....', '2006-10-23 08:50:01.000000', NULL, 1),
(2953695, 415671, 49109, '<td valign="top">way too dark in the foreground, otherwise nice scene</td>', 'way too dark in the foreground, otherwise nice scene', '2006-10-23 08:57:03.000000', NULL, 1),
(2953707, 414783, 35602, '<td valign="top">Nice placement of the train.  Like the dark contrast of the tunnel as a frame to it.  Would have liked to see less tunnel and more train.</td>', 'Nice placement of the train.  Like the dark contrast of the tunnel as a frame to it.  Would have liked to see less tunnel and more train.', '2006-10-23 09:04:32.000000', NULL, 1),
(2953724, 414423, 37719, '<td valign="top">Hmm...it is obvious the train is not moving.  The blur looks applied and can be seen in areas next to the wheel that shouldn''t be blurry even if the train was actually moving.  Also the rail is blurry which again, even if the train were moving, the rail isn''t and shouldn''t be blurry.</td>', 'Hmm...it is obvious the train is not moving.  The blur looks applied and can be seen in areas next to the wheel that shouldn''t be blurry even if the train was actually moving.  Also the rail is blurry which again, even if the train were moving, the rail isn''t and shouldn''t be blurry.', '2006-10-23 09:09:48.000000', NULL, 1),
(2953744, 414213, 32161, '<td valign="top">Ahhhhhh what a cutie! 8</td>', 'Ahhhhhh what a cutie! 8', '2006-10-23 09:21:37.000000', NULL, 1),
(2953747, 415489, 13610, '<td valign="top">Great shot and color. Would have been amazing if we had seen the locomotive.</td>', 'Great shot and color. Would have been amazing if we had seen the locomotive.', '2006-10-23 09:22:48.000000', NULL, 1),
(2953750, 415465, 13610, '<td valign="top">Excellent photojournalism shot</td>', 'Excellent photojournalism shot', '2006-10-23 09:23:34.000000', NULL, 1),
(2953753, 415611, 13610, '<td valign="top">Amazing!</td>', 'Amazing!', '2006-10-23 09:23:56.000000', NULL, 1),
(2953757, 415671, 13610, '<td valign="top">Good composition and environment. Too much contrast for my taste.</td>', 'Good composition and environment. Too much contrast for my taste.', '2006-10-23 09:25:42.000000', NULL, 1),
(2953760, 414521, 47597, '<td valign="top">What a wonderful pic! I love the contrast between the gritty, industrial tracks and gravel and the dreamy mystical forest behind. I do have a sense however, that a lot of processing has gone on (especially in the foreground - lots of burning?).</td>', 'What a wonderful pic! I love the contrast between the gritty, industrial tracks and gravel and the dreamy mystical forest behind. I do have a sense however, that a lot of processing has gone on (especially in the foreground - lots of burning?).', '2006-10-23 09:26:29.000000', NULL, 1),
(2953768, 415520, 13610, '<td valign="top">Fery good composition and lighting. A little bit on the oversharp side.</td>', 'Fery good composition and lighting. A little bit on the oversharp side.', '2006-10-23 09:30:30.000000', NULL, 1),
(2953789, 415109, 35994, '<td valign="top">great colors &amp; angle</td>', 'great colors & angle', '2006-10-23 09:44:31.000000', NULL, 1),
(2953792, 415651, 30049, '<td valign="top">Good idea.  Greater impact would have been made with a slower shutter speed to blur the train a little more IMO.  Good luck in the challenge.</td>', 'Good idea.  Greater impact would have been made with a slower shutter speed to blur the train a little more IMO.  Good luck in the challenge.', '2006-10-23 09:49:31.000000', NULL, 1),
(2953796, 415153, 30049, '<td valign="top">Nice, but I wish his face was in focus like his arm and glove are.  Good job of post-processing with the B/W tone.</td>', 'Nice, but I wish his face was in focus like his arm and glove are.  Good job of post-processing with the B/W tone.', '2006-10-23 09:55:07.000000', NULL, 1),
(2953802, 415671, 30049, '<td valign="top">I like it better thru the window pane.  This feels a bit under-exposed.  Looks like a neat place to visit.  Good luck in the challenge.</td>', 'I like it better thru the window pane.  This feels a bit under-exposed.  Looks like a neat place to visit.  Good luck in the challenge.', '2006-10-23 09:59:26.000000', NULL, 1),
(2953809, 415198, 18339, '<td valign="top">Beautiful colors and textures.  Best of luck, it looks like a winner to me.</td>', 'Beautiful colors and textures.  Best of luck, it looks like a winner to me.', '2006-10-23 10:01:55.000000', NULL, 1),
(2953813, 414423, 30049, '<td valign="top">Funny how only one spot appears to be in motion.  Hmmm...</td>', 'Funny how only one spot appears to be in motion.  Hmmm...', '2006-10-23 10:02:40.000000', NULL, 1),
(2953821, 415167, 3102, '<td valign="top">The editing on the sky is quite evident here, especially when looking at the trees.</td>', 'The editing on the sky is quite evident here, especially when looking at the trees.', '2006-10-23 10:06:17.000000', NULL, 1),
(2953826, 413838, 43383, '<td valign="top">very beautiful. good symmetrics</td>', 'very beautiful. good symmetrics', '2006-10-23 10:09:00.000000', NULL, 1),
(2953847, 413874, 30049, '<td valign="top">This looks to be a tough subject to photograph, at least close up, as many pieces are outside the focal plane.  The bottom 6 1/2 text and center indentation areas are fine, but much of the rest is not.  Also a little over-exposed with the lighting.</td>', 'This looks to be a tough subject to photograph, at least close up, as many pieces are outside the focal plane.  The bottom 6 1/2 text and center indentation areas are fine, but much of the rest is not.  Also a little over-exposed with the lighting.', '2006-10-23 10:18:16.000000', NULL, 1),
(2953852, 414223, 3102, '<td valign="top">Um... tripod?  Why would you submit something that has that much camera shake?</td>', 'Um... tripod?  Why would you submit something that has that much camera shake?', '2006-10-23 10:19:37.000000', NULL, 1),
(2953854, 415164, 30049, '<td valign="top">The London fog followed you onto the train!  :)</td>', 'The London fog followed you onto the train!  :)', '2006-10-23 10:19:52.000000', NULL, 1),
(2953857, 415167, 30049, '<td valign="top">In working the sky you went a tad overboard with your selection and lost detail/color in the trees.  Looks a little strange.</td>', 'In working the sky you went a tad overboard with your selection and lost detail/color in the trees.  Looks a little strange.', '2006-10-23 10:21:42.000000', NULL, 1),
(2953859, 414676, 30049, '<td valign="top">This documentary might have worked in black and white.  As is, the blue cast in the stone is distracting.  JMO of course.  Good luck in the challenge.</td>', 'This documentary might have worked in black and white.  As is, the blue cast in the stone is distracting.  JMO of course.  Good luck in the challenge.', '2006-10-23 10:22:59.000000', NULL, 1),
(2953862, 415222, 30049, '<td valign="top">Really like the processing here.  Great color tone.  Pleasing composition as well.  Good eye.  Best of luck to you in the challenge.</td>', 'Really like the processing here.  Great color tone.  Pleasing composition as well.  Good eye.  Best of luck to you in the challenge.', '2006-10-23 10:24:19.000000', NULL, 1),
(2953868, 414783, 3102, '<td valign="top">That''s a weird shot!  It defintely has me curious, since it looks like the train is heading for the tunnel, yet there don''t appear to be any tracks to be seen.  Odd...!</td>', 'That''s a weird shot!  It defintely has me curious, since it looks like the train is heading for the tunnel, yet there don''t appear to be any tracks to be seen.  Odd...!', '2006-10-23 10:25:45.000000', NULL, 1),
(2953895, 415564, 61191, '<td valign="top">Interesting, I love the metallic look and the skyline in the background!</td>', 'Interesting, I love the metallic look and the skyline in the background!', '2006-10-23 10:38:34.000000', NULL, 1),
(2953904, 413492, 61191, '<td valign="top">Overall a nice shot. Composition, colors and contrast are great. What really distracts me is your use of focus/sharpening: the wood is really sharp and crisp but the hinges are not. Thus detail gets lost and the viewers eye is drawn to the lower right corner of the shot.</td>', 'Overall a nice shot. Composition, colors and contrast are great. What really distracts me is your use of focus/sharpening: the wood is really sharp and crisp but the hinges are not. Thus detail gets lost and the viewers eye is drawn to the lower right corner of the shot.', '2006-10-23 10:41:32.000000', NULL, 1),
(2953908, 414623, 61191, '<td valign="top">Very cool shot! I love the atmosphere and the clean, simple composition. Great work!</td>', 'Very cool shot! I love the atmosphere and the clean, simple composition. Great work!', '2006-10-23 10:42:24.000000', NULL, 1),
(2953915, 415193, 13879, '<td valign="top">Dood! you may get hammered for the Datestamp!</td>', 'Dood! you may get hammered for the Datestamp!', '2006-10-23 10:44:58.000000', NULL, 1),
(2953919, 415519, 13879, '<td valign="top">Gotta ribbon! 10 from me</td>', 'Gotta ribbon! 10 from me', '2006-10-23 10:45:29.000000', NULL, 1),
(2953920, 415327, 61191, '<td valign="top">The selective desat works great - cool shot!</td>', 'The selective desat works great - cool shot!', '2006-10-23 10:45:45.000000', NULL, 1),
(2953926, 415177, 64175, '<td valign="top">Nice capture and presentation.  A fresh perspective for this challenge which is greatly appreciated.  10.</td>', 'Nice capture and presentation.  A fresh perspective for this challenge which is greatly appreciated.  10.', '2006-10-23 10:49:19.000000', NULL, 1),
(2953966, 415283, 30049, '<td valign="top">Bump the contrast and bring up the color saturation and you have something here.  As is, seems a little flat.  JMO of course.  Good luck in the challenge.</td>', 'Bump the contrast and bring up the color saturation and you have something here.  As is, seems a little flat.  JMO of course.  Good luck in the challenge.', '2006-10-23 11:03:06.000000', NULL, 1),
(2953968, 415097, 64929, '<td valign="top">A wee bit to orange IMHO but nice capture nonetheless</td>', 'A wee bit to orange IMHO but nice capture nonetheless', '2006-10-23 11:03:49.000000', NULL, 1),
(2953983, 414673, 51538, '<td valign="top">Like the morning light and cleanly presented image.</td>', 'Like the morning light and cleanly presented image.', '2006-10-23 11:08:07.000000', NULL, 1),
(2953987, 415412, 51538, '<td valign="top">Nice tint and composition.  The fish plate and wheel coincide making it even better.</td>', 'Nice tint and composition.  The fish plate and wheel coincide making it even better.', '2006-10-23 11:08:55.000000', NULL, 1),
(2953988, 414783, 51538, '<td valign="top">Exposure is quite nice on this countryside photo.</td>', 'Exposure is quite nice on this countryside photo.', '2006-10-23 11:09:26.000000', NULL, 1),
(2953989, 415430, 51538, '<td valign="top">Very pretty composition. 8.</td>', 'Very pretty composition. 8.', '2006-10-23 11:09:52.000000', NULL, 1),
(2953994, 415212, 51538, '<td valign="top">The colours are a bit disconcerting but overall I like the composition and effect. 7.</td>', 'The colours are a bit disconcerting but overall I like the composition and effect. 7.', '2006-10-23 11:10:38.000000', NULL, 1),
(2953999, 414281, 51538, '<td valign="top">Nice point of view and your processing of the image brings out nicely the iron and steel and typical textures of a railway station. 9.</td>', 'Nice point of view and your processing of the image brings out nicely the iron and steel and typical textures of a railway station. 9.', '2006-10-23 11:11:47.000000', NULL, 1),
(2954002, 414521, 51538, '<td valign="top">The intersection is interesting and the exposure good on your photo. 7.</td>', 'The intersection is interesting and the exposure good on your photo. 7.', '2006-10-23 11:13:02.000000', NULL, 1),
(2954007, 415327, 51538, '<td valign="top">Nicely composed photo and the specimen is well detailed in the DOF you selected.</td>', 'Nicely composed photo and the specimen is well detailed in the DOF you selected.', '2006-10-23 11:14:09.000000', NULL, 1),
(2954009, 415190, 50674, '<td valign="top">Takes me back to 1974 and a ride with CPR from Winnipeg to Vancouver, two days in Calgary on the way. What a trip.<br/>As for the shot :) I really like it, just wish it was bigger. Is it really 640? Fantastic background there.</td>', 'Takes me back to 1974 and a ride with CPR from Winnipeg to Vancouver, two days in Calgary on the way. What a trip.As for the shot :) I really like it, just wish it was bigger. Is it really 640? Fantastic background there.', '2006-10-23 11:14:29.000000', NULL, 1),
(2954013, 415156, 51538, '<td valign="top">I used to live out on the moors in Troon, Cornwall, when I worked in the tin mines there.  That was when a few bits of mail went to Troon in Scotland...  I like the selective desaturation fo colour you have used and the overall composition, IMO, is rather nice. 8.</td>', 'I used to live out on the moors in Troon, Cornwall, when I worked in the tin mines there.  That was when a few bits of mail went to Troon in Scotland...  I like the selective desaturation fo colour you have used and the overall composition, IMO, is rather nice. 8.', '2006-10-23 11:15:33.000000', NULL, 1),
(2954015, 415670, 51538, '<td valign="top">Nice story telling image. 7.</td>', 'Nice story telling image. 7.', '2006-10-23 11:15:57.000000', NULL, 1),
(2954017, 414738, 50674, '<td valign="top">Now that is what I call travelling in style. And the shot is great.</td>', 'Now that is what I call travelling in style. And the shot is great.', '2006-10-23 11:16:24.000000', NULL, 1),
(2954022, 415049, 64929, '<td valign="top">A little too much color, IMHO</td>', 'A little too much color, IMHO', '2006-10-23 11:17:43.000000', NULL, 1),
(2954023, 415481, 51538, '<td valign="top">Simple but effective image which retains the colour of the rusty ballast. 7.</td>', 'Simple but effective image which retains the colour of the rusty ballast. 7.', '2006-10-23 11:17:50.000000', NULL, 1),
(2954029, 415459, 51538, '<td valign="top">Nice sky that you managed to retain there along with the detail in the track. 7.</td>', 'Nice sky that you managed to retain there along with the detail in the track. 7.', '2006-10-23 11:18:45.000000', NULL, 1),
(2954031, 414307, 51538, '<td valign="top">Nice, unusual location. 8.</td>', 'Nice, unusual location. 8.', '2006-10-23 11:19:16.000000', NULL, 1),
(2954036, 415436, 51538, '<td valign="top">Nice symmetry and interesting colours.  All works very well to produce a modern image. 8.</td>', 'Nice symmetry and interesting colours.  All works very well to produce a modern image. 8.', '2006-10-23 11:20:04.000000', NULL, 1),
(2954039, 415214, 51538, '<td valign="top">Nice view of the tracks out west.  Pretty sky too. 8.</td>', 'Nice view of the tracks out west.  Pretty sky too. 8.', '2006-10-23 11:20:38.000000', NULL, 1),
(2954043, 415611, 51538, '<td valign="top">Nice idea indeed.  A little on the dark side - even though I like the dark side of this image.  7.</td>', 'Nice idea indeed.  A little on the dark side - even though I like the dark side of this image.  7.', '2006-10-23 11:21:28.000000', NULL, 1),
(2954046, 412678, 51538, '<td valign="top">Good find and nice lighting. 7.</td>', 'Good find and nice lighting. 7.', '2006-10-23 11:21:52.000000', NULL, 1),
(2954051, 415582, 51538, '<td valign="top">There must have been some interesting close up shots available on this engine. 7.</td>', 'There must have been some interesting close up shots available on this engine. 7.', '2006-10-23 11:22:35.000000', NULL, 1),
(2954053, 415110, 51538, '<td valign="top">Nice, unusual view point.  The city in the distance really enhances this image. 8.</td>', 'Nice, unusual view point.  The city in the distance really enhances this image. 8.', '2006-10-23 11:23:09.000000', NULL, 1),
(2954057, 415525, 51538, '<td valign="top">Lovely stereotypical photo of railyards. I like the tint. 8.</td>', 'Lovely stereotypical photo of railyards. I like the tint. 8.', '2006-10-23 11:24:03.000000', NULL, 1),
(2954061, 415587, 51538, '<td valign="top">Nice colours and the angle is interesting. 7.</td>', 'Nice colours and the angle is interesting. 7.', '2006-10-23 11:24:46.000000', NULL, 1),
(2954063, 415243, 51538, '<td valign="top">Very pretty processing effects and the detail is pleasing too. 8.</td>', 'Very pretty processing effects and the detail is pleasing too. 8.', '2006-10-23 11:25:11.000000', NULL, 1),
(2954067, 415389, 51538, '<td valign="top">Nice simple detail there. 7.</td>', 'Nice simple detail there. 7.', '2006-10-23 11:25:37.000000', NULL, 1),
(2954071, 415112, 51538, '<td valign="top">Nice in situ photo of a classic looking engine. 8.</td>', 'Nice in situ photo of a classic looking engine. 8.', '2006-10-23 11:26:26.000000', NULL, 1),
(2954076, 415435, 51538, '<td valign="top">Pretty overall effect and tint.  The experiment was worth while and adds something to the nicely desolate scene. 7.</td>', 'Pretty overall effect and tint.  The experiment was worth while and adds something to the nicely desolate scene. 7.', '2006-10-23 11:27:21.000000', NULL, 1),
(2954079, 415158, 51538, '<td valign="top">A lovely image and the wet night in Paris is especially pretty.  The bicycle enhances the photo more than the Deco station entrance.</td>', 'A lovely image and the wet night in Paris is especially pretty.  The bicycle enhances the photo more than the Deco station entrance.', '2006-10-23 11:28:06.000000', NULL, 1),
(2954081, 414623, 51538, '<td valign="top">Sparce, simple, but eloquent.  Not much really to say but that I like the effect a lot. 9.</td>', 'Sparce, simple, but eloquent.  Not much really to say but that I like the effect a lot. 9.', '2006-10-23 11:28:54.000000', NULL, 1),
(2954082, 413838, 51538, '<td valign="top">Nice simple symmetrical detail and the b/w enhances the image. 9.</td>', 'Nice simple symmetrical detail and the b/w enhances the image. 9.', '2006-10-23 11:29:19.000000', NULL, 1),
(2954084, 414027, 51538, '<td valign="top">Nice movement you managed to cpature. 8.</td>', 'Nice movement you managed to cpature. 8.', '2006-10-23 11:29:50.000000', NULL, 1),
(2954086, 415629, 51538, '<td valign="top">Nice story in the photo.  The colours and splendid steep mountainside really make this image stand out. 7.</td>', 'Nice story in the photo.  The colours and splendid steep mountainside really make this image stand out. 7.', '2006-10-23 11:30:55.000000', NULL, 1),
(2954089, 414677, 51538, '<td valign="top">Nice high contrast and small aperture.  It all works well together with the symmetry. 8.</td>', 'Nice high contrast and small aperture.  It all works well together with the symmetry. 8.', '2006-10-23 11:32:15.000000', NULL, 1),
(2954095, 413454, 51538, '<td valign="top">Nicely composed and the tint is pleasant. 9.</td>', 'Nicely composed and the tint is pleasant. 9.', '2006-10-23 11:35:55.000000', NULL, 1),
(2954099, 415222, 51538, '<td valign="top">Lovely detail.  The bolts are symbolic or strength and solidarity.  Nice work. 8.</td>', 'Lovely detail.  The bolts are symbolic or strength and solidarity.  Nice work. 8.', '2006-10-23 11:37:39.000000', NULL, 1),
(2954100, 414485, 24715, '<td valign="top">Ha, 300ZXTT! Nice bokeh, too!</td>', 'Ha, 300ZXTT! Nice bokeh, too!', '2006-10-23 11:38:01.000000', NULL, 1),
(2954101, 415245, 51538, '<td valign="top">Nicely processed.  The colours seem muted but entirely pleasing. 9.</td>', 'Nicely processed.  The colours seem muted but entirely pleasing. 9.', '2006-10-23 11:38:17.000000', NULL, 1),
(2954103, 415446, 24715, '<td valign="top">Great sky and the composition. I like the rails going into the distance.</td>', 'Great sky and the composition. I like the rails going into the distance.', '2006-10-23 11:38:35.000000', NULL, 1),
(2954106, 415523, 33672, '<td valign="top">Nice comp and curves.</td>', 'Nice comp and curves.', '2006-10-23 11:39:22.000000', NULL, 1),
(2954119, 415665, 24715, '<td valign="top">Not sure if I like the blur. Looks fake. However, the composition and colours are great.</td>', 'Not sure if I like the blur. Looks fake. However, the composition and colours are great.', '2006-10-23 11:44:14.000000', NULL, 1),
(2954125, 415049, 24715, '<td valign="top">Great photo. Too bad the sky is lacking the detail...</td>', 'Great photo. Too bad the sky is lacking the detail...', '2006-10-23 11:45:03.000000', NULL, 1),
(2954136, 413351, 24715, '<td valign="top">Great composition. I like the sepia effect also. One of the best in this challenge.</td>', 'Great composition. I like the sepia effect also. One of the best in this challenge.', '2006-10-23 11:48:38.000000', NULL, 1),
(2954143, 415650, 35545, '<td valign="top">That''s "gauge"!<br/> <br/>You''ve got a nice, clear scene, but to me, the main interest is the smoke, not the train.</td>', 'That''s "gauge"! You''ve got a nice, clear scene, but to me, the main interest is the smoke, not the train.', '2006-10-23 11:52:30.000000', NULL, 1),
(2954144, 415437, 29293, '<td valign="top">the sky is kind of vlown out</td>', 'the sky is kind of vlown out', '2006-10-23 11:53:07.000000', NULL, 1),
(2954148, 415242, 29293, '<td valign="top">nice motion blur</td>', 'nice motion blur', '2006-10-23 11:53:39.000000', NULL, 1),
(2954149, 415602, 35545, '<td valign="top">Nice picture and on topic, but I''d like it better if it was a straight b&amp;w -- not a color cast.</td>', 'Nice picture and on topic, but I''d like it better if it was a straight b&w -- not a color cast.', '2006-10-23 11:53:53.000000', NULL, 1);
