(2954150, 415452, 24715, '<td valign="top">This is great. The pose, B&amp;W choice and the texture work well in this composition.</td>', 'This is great. The pose, B&W choice and the texture work well in this composition.', '2006-10-23 11:54:04.000000', NULL, 1),
(2954152, 415671, 35545, '<td valign="top">I wish we could see more detail in the back platform of the caboose.</td>', 'I wish we could see more detail in the back platform of the caboose.', '2006-10-23 11:54:23.000000', NULL, 1),
(2954157, 415443, 29293, '<td valign="top">nice perspective</td>', 'nice perspective', '2006-10-23 11:55:33.000000', NULL, 1),
