(2954948, 415233, 30049, '<td valign="top">I could buy this more if it was titled ''Polar Express''.  That was the movie (with Tom Hanks) where the train goes to the north pole and the tracks run across/into a body of ice on the way there.  As is, this is more of an image about northern lights with a side show/prop of a piece of railroad track.</td>', 'I could buy this more if it was titled ''Polar Express''.  That was the movie (with Tom Hanks) where the train goes to the north pole and the tracks run across/into a body of ice on the way there.  As is, this is more of an image about northern lights with a side show/prop of a piece of railroad track.', '2006-10-23 16:42:40.000000', NULL, 1),
(2954949, 415604, 53095, '<td valign="top">The first original shot I''ve seen in this challenge, congrats.</td>', 'The first original shot I''ve seen in this challenge, congrats.', '2006-10-23 16:42:43.000000', NULL, 1),
(2954950, 414232, 30049, '<td valign="top">Don''t really care for the extreme processing.  Sorry.</td>', 'Don''t really care for the extreme processing.  Sorry.', '2006-10-23 16:43:05.000000', NULL, 1),
(2954952, 413492, 30049, '<td valign="top">This is an interesting image.  I wish you didn''t have to rely on the title so much to get the point across.  Nice color and texture.  Good luck in the challenge.</td>', 'This is an interesting image.  I wish you didn''t have to rely on the title so much to get the point across.  Nice color and texture.  Good luck in the challenge.', '2006-10-23 16:44:23.000000', NULL, 1),
(2954955, 414710, 30049, '<td valign="top">Kind of a fun high contrast image.  Might be a bit too contrasty to please the majority of DPC voters.  Good luck.</td>', 'Kind of a fun high contrast image.  Might be a bit too contrasty to please the majority of DPC voters.  Good luck.', '2006-10-23 16:45:31.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2954958, 415168, 53095, '<td valign="top">Gorgeous angle and beautiful lines in this shot.</td>', 'Gorgeous angle and beautiful lines in this shot.', '2006-10-23 16:46:57.000000', NULL, 1),
(2954963, 415361, 30049, '<td valign="top">Nice POV.  The image looks a little hazy (dust from somewhere else perhaps?).  The train engine almost appears like a toy from this angle.  Overall I like it.  Good luck.</td>', 'Nice POV.  The image looks a little hazy (dust from somewhere else perhaps?).  The train engine almost appears like a toy from this angle.  Overall I like it.  Good luck.', '2006-10-23 16:47:27.000000', NULL, 1),
(2954967, 414420, 30049, '<td valign="top">Hey!  How''d all that snow get on the branches but not on the ground?!  Oh wait, that''s one of those funny looking IR filter thingees.  :D  Sorry, not really a fan of IR, but those that enjoy it should like this one.  Good luck.</td>', 'Hey!  How''d all that snow get on the branches but not on the ground?!  Oh wait, that''s one of those funny looking IR filter thingees.  :D  Sorry, not really a fan of IR, but those that enjoy it should like this one.  Good luck.', '2006-10-23 16:48:55.000000', NULL, 1),
(2954973, 415193, 53095, '<td valign="top">So much potential in this shot, it really looks beautiful if I squint...only two things wrong with it and I''m sure you''ve heard them already.</td>', 'So much potential in this shot, it really looks beautiful if I squint...only two things wrong with it and I''m sure you''ve heard them already.', '2006-10-23 16:51:07.000000', NULL, 1),
(2954982, 415177, 30049, '<td valign="top">Hey.  That''s cheating.  Well, not really, but it feels that way.  :D  Seeing how the challenge theme is trains &amp; railroads I''ll evaluate the image within your image.  Hmmm...tracks are a bit centered and I wish they didn''t end so abruptly.  Sky is "ok", bit on the ho-hum side.  Color saturation is good, although I wonder how it would look in B/W?  Oops, then it wouldn''t look right with the black bg and white mat.  Oh well.  Cute.  Good luck.</td>', 'Hey.  That''s cheating.  Well, not really, but it feels that way.  :D  Seeing how the challenge theme is trains & railroads I''ll evaluate the image within your image.  Hmmm...tracks are a bit centered and I wish they didn''t end so abruptly.  Sky is "ok", bit on the ho-hum side.  Color saturation is good, although I wonder how it would look in B/W?  Oops, then it wouldn''t look right with the black bg and white mat.  Oh well.  Cute.  Good luck.', '2006-10-23 16:53:06.000000', NULL, 1),
(2954988, 414204, 53095, '<td valign="top">Should have focused in on the 2nd spike and not the rock.</td>', 'Should have focused in on the 2nd spike and not the rock.', '2006-10-23 16:54:49.000000', NULL, 1),
(2954992, 414603, 53095, '<td valign="top">Majestic looking shot.</td>', 'Majestic looking shot.', '2006-10-23 16:56:35.000000', NULL, 1),
(2955013, 415671, 5354, '<td valign="top">Lost a little detail in the shadows, but a nice enough image.</td>', 'Lost a little detail in the shadows, but a nice enough image.', '2006-10-23 17:05:43.000000', NULL, 1),
(2955016, 415283, 5354, '<td valign="top">Nice repetition, but not much atmosphere. Maybe an early morning, or even a nigt shot might work better.</td>', 'Nice repetition, but not much atmosphere. Maybe an early morning, or even a nigt shot might work better.', '2006-10-23 17:06:42.000000', NULL, 1),
(2955024, 415472, 37444, '<td valign="top">Meets Challenge - 2<br/>Creativity - 2<br/>Technical Stuff - 2<br/>Overall Appeal - 1<br/>Biased Wow - 0<br/>Total = 7<br/>Taking a bit off the top so that the bright spot does not interfere with the subject might be better.</td>', 'Meets Challenge - 2Creativity - 2Technical Stuff - 2Overall Appeal - 1Biased Wow - 0Total = 7Taking a bit off the top so that the bright spot does not interfere with the subject might be better.', '2006-10-23 17:09:21.000000', NULL, 1),
(2955025, 415198, 36988, '<td valign="top">Beautifully done. Rotating a degree clockwise might have been in order but that is being nitpicky. Good is good!</td>', 'Beautifully done. Rotating a degree clockwise might have been in order but that is being nitpicky. Good is good!', '2006-10-23 17:09:33.000000', NULL, 1),
