(2955449, 414027, 59740, '<td valign="top">great capture and color. I love the motion blur of the background.</td>', 'great capture and color. I love the motion blur of the background.', '2006-10-23 19:36:40.000000', NULL, 1),
(2955450, 415472, 19944, '<td valign="top">This is a great shot.  The leading lines of the tracks are wonderful and I really like the lens flair.</td>', 'This is a great shot.  The leading lines of the tracks are wonderful and I really like the lens flair.', '2006-10-23 19:36:42.000000', NULL, 1),
(2955455, 414204, 19944, '<td valign="top">Oh, this would have been really special if you had gotten that second spike in sharper focus.  Nice try, though.</td>', 'Oh, this would have been really special if you had gotten that second spike in sharper focus.  Nice try, though.', '2006-10-23 19:37:39.000000', NULL, 1),
