(2955497, 415527, 51538, '<td valign="top">And now the roads are choked with cars.  The story of Los Angeles, the story of the rail cuts in the 50s UK too....</td>', 'And now the roads are choked with cars.  The story of Los Angeles, the story of the rail cuts in the 50s UK too....', '2006-10-23 19:53:17.000000', NULL, 1),
(2955501, 415168, 51538, '<td valign="top">Nice point of view.  Lovely geometry of composition. 8.</td>', 'Nice point of view.  Lovely geometry of composition. 8.', '2006-10-23 19:54:12.000000', NULL, 1),
(2955502, 415198, 59740, '<td valign="top">Model looks too well composed and clean for this scene.</td>', 'Model looks too well composed and clean for this scene.', '2006-10-23 19:54:20.000000', NULL, 1),
(2955504, 415634, 64795, '<td valign="top">I like how the track lines lead your eyes.  I''m not so sure about the lighting though.  Something seems to be missing.</td>', 'I like how the track lines lead your eyes.  I''m not so sure about the lighting though.  Something seems to be missing.', '2006-10-23 19:54:40.000000', NULL, 1),
