(2955510, 415167, 59740, '<td valign="top">Excellent sharpness and dark sky.</td>', 'Excellent sharpness and dark sky.', '2006-10-23 19:55:26.000000', NULL, 1),
(2955512, 414652, 64795, '<td valign="top">Interesting editing.  It definitely gives it a desolate feel, which works well for your title.</td>', 'Interesting editing.  It definitely gives it a desolate feel, which works well for your title.', '2006-10-23 19:55:53.000000', NULL, 1),
(2955517, 414204, 64795, '<td valign="top">Good idea, but I feel like the thing that is in most focus is the rock on the left side.</td>', 'Good idea, but I feel like the thing that is in most focus is the rock on the left side.', '2006-10-23 19:56:48.000000', NULL, 1),
(2955518, 415564, 51538, '<td valign="top">Nicely done.  I think that is the F train at Smith and 9 in/near Redhook, is it not?  The b/w treatment is great.  I can''t fault your photo. 10.</td>', 'Nicely done.  I think that is the F train at Smith and 9 in/near Redhook, is it not?  The b/w treatment is great.  I can''t fault your photo. 10.', '2006-10-23 19:57:07.000000', NULL, 1),
