(2955520, 415262, 64795, '<td valign="top">This has a nice feel to it with B&amp;W.  I like what she is wearing too..it seems natural.</td>', 'This has a nice feel to it with B&W.  I like what she is wearing too..it seems natural.', '2006-10-23 19:57:31.000000', NULL, 1),
(2955526, 414669, 64795, '<td valign="top">I like the angle, and how the picture has a colder color cast.  It works well for the title.</td>', 'I like the angle, and how the picture has a colder color cast.  It works well for the title.', '2006-10-23 19:58:26.000000', NULL, 1),
(2955527, 415340, 64795, '<td valign="top">Oooh.. that is great! I love the textures!</td>', 'Oooh.. that is great! I love the textures!', '2006-10-23 19:58:49.000000', NULL, 1),
(2955528, 415520, 64795, '<td valign="top">That is an awesome train.  Good capture!</td>', 'That is an awesome train.  Good capture!', '2006-10-23 19:59:20.000000', NULL, 1),
