(2956336, 415596, 59740, '<td valign="top">Excellent.</td>', 'Excellent.', '2006-10-24 00:50:20.000000', NULL, 1),
(2956344, 415233, 64446, '<td valign="top">The background is wonderful. The forground is awful. That doesn''t mean it is bad, just surreal... I am going to credit it for such a creativity. I think this will shake the average observer paradigm of what a "nice" image is (or should be). Good job.</td>', 'The background is wonderful. The forground is awful. That doesn''t mean it is bad, just surreal... I am going to credit it for such a creativity. I think this will shake the average observer paradigm of what a "nice" image is (or should be). Good job.', '2006-10-24 00:52:15.000000', NULL, 1),
(2956350, 414307, 59740, '<td valign="top">A lot of interesting material. Actually too much. It''s hard to settle on a subject.</td>', 'A lot of interesting material. Actually too much. It''s hard to settle on a subject.', '2006-10-24 00:53:05.000000', NULL, 1),
(2956353, 414450, 59740, '<td valign="top">This picture would have much more impact if taken with a longer telephoto or cropped severely. Too much uninteresting sky.</td>', 'This picture would have much more impact if taken with a longer telephoto or cropped severely. Too much uninteresting sky.', '2006-10-24 00:54:11.000000', NULL, 1),
(2956361, 415326, 59740, '<td valign="top">Nice color. could be a little sharper and would look better with the horizontal lines actually horizontal.</td>', 'Nice color. could be a little sharper and would look better with the horizontal lines actually horizontal.', '2006-10-24 00:55:53.000000', NULL, 1),
(2956363, 415508, 36956, '<td valign="top">I like the trains lights in the background.  It works well.</td>', 'I like the trains lights in the background.  It works well.', '2006-10-24 00:56:07.000000', NULL, 1),
(2956368, 414291, 36956, '<td valign="top">very creative.  An original idea... I like the desaturation, except the mans face appears a little blue to me, other than that... wonderful.</td>', 'very creative.  An original idea... I like the desaturation, except the mans face appears a little blue to me, other than that... wonderful.', '2006-10-24 00:56:54.000000', NULL, 1),
