(2956947, 415611, 40386, '<td valign="top">My favorite shot of the challenge, says it all but with simplicity!  Good luck 10</td>', 'My favorite shot of the challenge, says it all but with simplicity!  Good luck 10', '2006-10-24 08:25:50.000000', NULL, 1),
(2957031, 415112, 64928, '<td valign="top">You caught this one at just the right time.  The curve of the track, the puff of steam, the lighting all work together to create a great work of art.</td>', 'You caught this one at just the right time.  The curve of the track, the puff of steam, the lighting all work together to create a great work of art.', '2006-10-24 09:28:04.000000', NULL, 1),
