(2960001, 415233, 21026, '<td valign="top">Great picture, but that looks like a boat launch more then train tracks.  Tracks look staged.</td>', 'Great picture, but that looks like a boat launch more then train tracks.  Tracks look staged.', '2006-10-25 03:52:38.000000', NULL, 1),
(2960012, 415435, 21026, '<td valign="top">Would have been a perfect 10 with out the canvas filter.</td>', 'Would have been a perfect 10 with out the canvas filter.', '2006-10-25 03:55:26.000000', NULL, 1),
(2960014, 414673, 63503, '<td valign="top">Very nice capture</td>', 'Very nice capture', '2006-10-25 03:55:45.000000', NULL, 1),
