(2963365, 412678, 30982, '<td valign="top">How rather sad.  Hopefully it''s being repaired and restored?</td>', 'How rather sad.  Hopefully it''s being repaired and restored?', '2006-10-25 21:27:31.000000', NULL, 1),
(2963368, 415508, 30982, '<td valign="top">Heh!  Always nice to have spare engineers hitchhiking...  Nice different approach to the challenge!</td>', 'Heh!  Always nice to have spare engineers hitchhiking...  Nice different approach to the challenge!', '2006-10-25 21:28:01.000000', NULL, 1),
(2963376, 415109, 30982, '<td valign="top">Great color contrast!  Though you''d lose a bit of the train, I''d crop off the left a bit to get rid of the orange in the background.  Nice angle, too!</td>', 'Great color contrast!  Though you''d lose a bit of the train, I''d crop off the left a bit to get rid of the orange in the background.  Nice angle, too!', '2006-10-25 21:30:00.000000', NULL, 1),
(2963377, 415629, 30982, '<td valign="top">The soft glow gives this a vintage kinda feel.</td>', 'The soft glow gives this a vintage kinda feel.', '2006-10-25 21:30:26.000000', NULL, 1),
(2963380, 413645, 30982, '<td valign="top">Meets the challenge and the sky is quite nice, but it''s a bit on the bland side.</td>', 'Meets the challenge and the sky is quite nice, but it''s a bit on the bland side.', '2006-10-25 21:31:01.000000', NULL, 1),
(2963381, 415594, 30982, '<td valign="top">Nice shot of a toy railroad car!</td>', 'Nice shot of a toy railroad car!', '2006-10-25 21:31:18.000000', NULL, 1),
(2963387, 415113, 30982, '<td valign="top">Very interesting effect!</td>', 'Very interesting effect!', '2006-10-25 21:32:26.000000', NULL, 1),
(2963392, 414953, 30982, '<td valign="top">And in this case, D for desolate.  A bit on the bright and sorta flat contrast-wise side, but a nice composition.</td>', 'And in this case, D for desolate.  A bit on the bright and sorta flat contrast-wise side, but a nice composition.', '2006-10-25 21:33:24.000000', NULL, 1),
(2963476, 414521, 30982, '<td valign="top">What a lovely place for a walk!</td>', 'What a lovely place for a walk!', '2006-10-25 22:05:38.000000', NULL, 1),
(2963480, 415568, 30982, '<td valign="top">I like the comic juxtaposition of the no smoking sticker and the very obviously smoking smokestack on the train.</td>', 'I like the comic juxtaposition of the no smoking sticker and the very obviously smoking smokestack on the train.', '2006-10-25 22:06:47.000000', NULL, 1),
(2963486, 415666, 30982, '<td valign="top">Needs better graffiti, too - get some talented youths out there.  Lovely blue sky!</td>', 'Needs better graffiti, too - get some talented youths out there.  Lovely blue sky!', '2006-10-25 22:07:30.000000', NULL, 1),
(2963492, 415049, 30982, '<td valign="top">A very scenic choice and well composed.  The reds are bit overpowering for my taste, though.</td>', 'A very scenic choice and well composed.  The reds are bit overpowering for my taste, though.', '2006-10-25 22:11:51.000000', NULL, 1),
(2963504, 415472, 30982, '<td valign="top">This makes me smile.  This is the way I love to look at tracks when the sun is just right - just as you have it here.  The glint of the lines, the glare of the sun.  Nice.</td>', 'This makes me smile.  This is the way I love to look at tracks when the sun is just right - just as you have it here.  The glint of the lines, the glare of the sun.  Nice.', '2006-10-25 22:16:21.000000', NULL, 1),
(2963507, 415167, 30982, '<td valign="top">A great subject for this challenge, but the processing makes it just a tad too dark/flat to really show it off nicely.</td>', 'A great subject for this challenge, but the processing makes it just a tad too dark/flat to really show it off nicely.', '2006-10-25 22:17:14.000000', NULL, 1),
(2963512, 415436, 30982, '<td valign="top">Very nifty perspective!  Thanks for giving us a different look at things.</td>', 'Very nifty perspective!  Thanks for giving us a different look at things.', '2006-10-25 22:19:04.000000', NULL, 1),
(2963516, 415465, 30982, '<td valign="top">Heh - someone DID get the derailment.  Nice job!</td>', 'Heh - someone DID get the derailment.  Nice job!', '2006-10-25 22:19:52.000000', NULL, 1),
(2963527, 415533, 30982, '<td valign="top">Love the yellow line and the sense of motion!</td>', 'Love the yellow line and the sense of motion!', '2006-10-25 22:24:05.000000', NULL, 1),
(2963530, 415435, 30982, '<td valign="top">The use of the texture creates an interesting effect here - like the paper itself is just behind the pole, and the shadow of the line running between the poles is falling on that paper.</td>', 'The use of the texture creates an interesting effect here - like the paper itself is just behind the pole, and the shadow of the line running between the poles is falling on that paper.', '2006-10-25 22:25:03.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2963533, 414423, 30982, '<td valign="top">What I can''t figure is how it looks like the wheel is moving but no other part of the train is.  Interesting perspective, though!</td>', 'What I can''t figure is how it looks like the wheel is moving but no other part of the train is.  Interesting perspective, though!', '2006-10-25 22:26:15.000000', NULL, 1),
(2963539, 415168, 30982, '<td valign="top">Very nice angle and choice of tones for this.  Only nit is I keep trying to scroll up just a bit.  On the other hand, if I scroll down to just the top of the front of the car, I don''t feel as though anything is missing from the top.  Still a very effective photograph.</td>', 'Very nice angle and choice of tones for this.  Only nit is I keep trying to scroll up just a bit.  On the other hand, if I scroll down to just the top of the front of the car, I don''t feel as though anything is missing from the top.  Still a very effective photograph.', '2006-10-25 22:27:38.000000', NULL, 1),
(2963541, 413838, 30982, '<td valign="top">Love the symmetry in this and the "fade into the mist" part.  Good choice to use a fairly deep DOF and let the mist do the rest.</td>', 'Love the symmetry in this and the "fade into the mist" part.  Good choice to use a fairly deep DOF and let the mist do the rest.', '2006-10-25 22:28:59.000000', NULL, 1),
(2963560, 414870, 30982, '<td valign="top">The solitary figure with the bubbles of light make this seem almost otherworldly.  You could crank the levels down even further to fade the background/right side to black and it gets even stronger - isolates the man even more.  Nice shot!</td>', 'The solitary figure with the bubbles of light make this seem almost otherworldly.  You could crank the levels down even further to fade the background/right side to black and it gets even stronger - isolates the man even more.  Nice shot!', '2006-10-25 22:33:09.000000', NULL, 1),
(2963564, 415587, 30982, '<td valign="top">The tilt is disconcerting and quite interesting!</td>', 'The tilt is disconcerting and quite interesting!', '2006-10-25 22:33:30.000000', NULL, 1),
(2963567, 414420, 30982, '<td valign="top">I''m not a big fan of IR (but I''m a minority) but I do like the almost fairy-tale quality of this.  The switch in the foreground makes the composition for me.</td>', 'I''m not a big fan of IR (but I''m a minority) but I do like the almost fairy-tale quality of this.  The switch in the foreground makes the composition for me.', '2006-10-25 22:35:15.000000', NULL, 1),
(2963569, 414281, 30982, '<td valign="top">The lighting and the composition carry the picture; and it''s not just grunge for the heck of it - it complements the scene very well.</td>', 'The lighting and the composition carry the picture; and it''s not just grunge for the heck of it - it complements the scene very well.', '2006-10-25 22:37:59.000000', NULL, 1),
(2963574, 415453, 30982, '<td valign="top">Nicely seen and captured!  And looks a lot like the location of at least one other shot in the challenge, too.  I really like the effect of the natural framing through the window.</td>', 'Nicely seen and captured!  And looks a lot like the location of at least one other shot in the challenge, too.  I really like the effect of the natural framing through the window.', '2006-10-25 22:39:36.000000', NULL, 1),
(2963631, 415485, 62318, '<td valign="top">I voted this one low mostly due to subject. It is pretty lifeless.</td>', 'I voted this one low mostly due to subject. It is pretty lifeless.', '2006-10-25 23:04:25.000000', NULL, 1),
(2963637, 414652, 62318, '<td valign="top">There is way too much contrast for me, so I gave it a low score (3). I believe the contrast makes the image worse and feels contrived.</td>', 'There is way too much contrast for me, so I gave it a low score (3). I believe the contrast makes the image worse and feels contrived.', '2006-10-25 23:05:57.000000', NULL, 1),
(2963642, 414223, 62318, '<td valign="top">Lacks composition and technique. Putting the camera on a post or on the ground would have bumped it up to at least a 4 for me. It is a 3 right now.</td>', 'Lacks composition and technique. Putting the camera on a post or on the ground would have bumped it up to at least a 4 for me. It is a 3 right now.', '2006-10-25 23:07:09.000000', NULL, 1),
(2963643, 414485, 62318, '<td valign="top">The shot is nice, but I voted low because it just looks like the challenge was an afterthought. 3.</td>', 'The shot is nice, but I voted low because it just looks like the challenge was an afterthought. 3.', '2006-10-25 23:07:17.000000', NULL, 1),
(2963663, 415526, 34396, '<td valign="top">An interesting shot and a neat looking train.  The sky is a little blown out at the right hand side of the frame.  It might have been lessened if you changed your position by moving up the track a bit more and getting a shot of the front of the loco, but also including the side of the cars on left going into the distance.  Don''t know if I explained that correctly, but good work just the same.</td>', 'An interesting shot and a neat looking train.  The sky is a little blown out at the right hand side of the frame.  It might have been lessened if you changed your position by moving up the track a bit more and getting a shot of the front of the loco, but also including the side of the cars on left going into the distance.  Don''t know if I explained that correctly, but good work just the same.', '2006-10-25 23:14:43.000000', NULL, 1),
(2963670, 415198, 62318, '<td valign="top">Yes. Very nice picture. Great PP work and great composition. My favorite image in the challenge. 9.</td>', 'Yes. Very nice picture. Great PP work and great composition. My favorite image in the challenge. 9.', '2006-10-25 23:16:38.000000', NULL, 1),
(2963671, 414213, 62318, '<td valign="top">Cute idea. Works well with the theme. Nice composition. Not much I would change, I would just be nickpicking (saturation levels...). 8.</td>', 'Cute idea. Works well with the theme. Nice composition. Not much I would change, I would just be nickpicking (saturation levels...). 8.', '2006-10-25 23:16:59.000000', NULL, 1),
(2963679, 415137, 34396, '<td valign="top">I like the various colors of rust on this shot.  The contrasting green &amp; white add interest as well.  I''m left wanting to see more of this relic, but don''t know if seeing more would have made it better.</td>', 'I like the various colors of rust on this shot.  The contrasting green & white add interest as well.  I''m left wanting to see more of this relic, but don''t know if seeing more would have made it better.', '2006-10-25 23:21:37.000000', NULL, 1),
(2963785, 414677, 30982, '<td valign="top">I quite like the centered perspective.  The only detraction is the cars on the left - maybe you should have had them towed.  (Just kidding!)</td>', 'I quite like the centered perspective.  The only detraction is the cars on the left - maybe you should have had them towed.  (Just kidding!)', '2006-10-25 23:50:33.000000', NULL, 1),
(2963804, 415471, 30982, '<td valign="top">I like the title and you captured the motion of the train well, but you also captured motion of the foreground somehow which kinda detracts.</td>', 'I like the title and you captured the motion of the train well, but you also captured motion of the foreground somehow which kinda detracts.', '2006-10-25 23:53:47.000000', NULL, 1),
(2963829, 415467, 30982, '<td valign="top">I really like the repetition of the handles and the pink color with the pale blue.  Nicely seen and captured.</td>', 'I really like the repetition of the handles and the pink color with the pale blue.  Nicely seen and captured.', '2006-10-25 23:59:57.000000', NULL, 1),
(2963832, 414591, 30982, '<td valign="top">Very nice!  Love the very not usual view of the Eye thing - the inclusion of the sign is excellent.</td>', 'Very nice!  Love the very not usual view of the Eye thing - the inclusion of the sign is excellent.', '2006-10-26 00:00:54.000000', NULL, 1),
(2963837, 413351, 30982, '<td valign="top">There are several shots like this in the challenge, but this one grabs me.  I''m trying to figure out why.  I think it''s the near silhouette of the spike, the clarity of the raised lettering on the side of the rail, and the placement of the line of the rail itself in the frame.  The play of light seems just right, too.</td>', 'There are several shots like this in the challenge, but this one grabs me.  I''m trying to figure out why.  I think it''s the near silhouette of the spike, the clarity of the raised lettering on the side of the rail, and the placement of the line of the rail itself in the frame.  The play of light seems just right, too.', '2006-10-26 00:02:56.000000', NULL, 1),
(2964235, 415100, 39243, '<td valign="top">great photo - I only know it belongs in this challenge because of the title though. normally i would give this a 7 or an 8 but due to no train - 5. Ok there are a bunch of other photos with no train so you get your 8.</td>', 'great photo - I only know it belongs in this challenge because of the title though. normally i would give this a 7 or an 8 but due to no train - 5. Ok there are a bunch of other photos with no train so you get your 8.', '2006-10-26 04:03:05.000000', NULL, 1),
(2964511, 415186, 38032, '<td valign="top">impressive location / action</td>', 'impressive location / action', '2006-10-26 09:14:57.000000', NULL, 1),
(2964516, 412678, 38032, '<td valign="top">cool - I love this sorta stuff - it might have been a tad more exciting with a more centered - of off-center composition. 7</td>', 'cool - I love this sorta stuff - it might have been a tad more exciting with a more centered - of off-center composition. 7', '2006-10-26 09:16:54.000000', NULL, 1),
(2964587, 415198, 61234, '<td valign="top">Here it is. The one I pick to take the blue. Why? Everything is spot on. Color tones, composition and mood. Great shot. Congrats!</td>', 'Here it is. The one I pick to take the blue. Why? Everything is spot on. Color tones, composition and mood. Great shot. Congrats!', '2006-10-26 09:44:51.000000', NULL, 1),
(2964591, 413324, 61234, '<td valign="top">A ribbon winner for sure in my book. Love the rich rust tones. Excellent job!</td>', 'A ribbon winner for sure in my book. Love the rich rust tones. Excellent job!', '2006-10-26 09:45:38.000000', NULL, 1),
(2964595, 415477, 61234, '<td valign="top">Wonderful vantage point. I think this will do well for itself. Congrats!</td>', 'Wonderful vantage point. I think this will do well for itself. Congrats!', '2006-10-26 09:46:50.000000', NULL, 1),
(2964600, 413838, 61234, '<td valign="top">A top pick for me. Nice mood and vantage. Excellent work!</td>', 'A top pick for me. Nice mood and vantage. Excellent work!', '2006-10-26 09:47:33.000000', NULL, 1),
(2964602, 415245, 61234, '<td valign="top">The colors attract me to this. Nice work!</td>', 'The colors attract me to this. Nice work!', '2006-10-26 09:48:09.000000', NULL, 1),
(2964607, 414307, 61234, '<td valign="top">There is so much to see here. Intricate workings of days gone by. Wonderful work. Sure to do well.</td>', 'There is so much to see here. Intricate workings of days gone by. Wonderful work. Sure to do well.', '2006-10-26 09:49:17.000000', NULL, 1),
(2964612, 415474, 61234, '<td valign="top">Help is on the way:) I score this to do well. It put a smile on my face, and that''s always a good thing. Nice job!</td>', 'Help is on the way:) I score this to do well. It put a smile on my face, and that''s always a good thing. Nice job!', '2006-10-26 09:50:20.000000', NULL, 1),
(2964614, 415453, 61234, '<td valign="top">A top pick for me because it stands apart from the rest and I like what you achieved. Congrats!</td>', 'A top pick for me because it stands apart from the rest and I like what you achieved. Congrats!', '2006-10-26 09:51:07.000000', NULL, 1),
(2964639, 413169, 50034, '<td valign="top">I was just about to declare DNMC, but then I saw the "token" railroad tracks.  IMHO RR or train is not actually the subject of this photo.  The determined cyclist is the subject.  Now, technically I''m seeing some pretty fine hyperfocal distance which makes the title, <b>City Life</b>.  :)</td>', 'I was just about to declare DNMC, but then I saw the "token" railroad tracks.  IMHO RR or train is not actually the subject of this photo.  The determined cyclist is the subject.  Now, technically I''m seeing some pretty fine hyperfocal distance which makes the title, City Life.  :)', '2006-10-26 10:05:29.000000', NULL, 1),
(2964676, 414593, 50034, '<td valign="top">My eye seems to be equally drawn to the well-focused trees as much as the RR tracks.  I <b>do</b> like your creative efforts compositionally, and the tracks are acceptably well-focused, even though the tree limb seems to be the point of your camera''s auto-focus sensor.  <i>A simple, but effective near-instant improvement IMHO would be to select the bottom half (just below the needles) in even a simple editting program, like Broderbund''s Print Shop 15 (or Classic.)  Then, increase contrast &amp; brightness on the selected.  Follow-up with select inverse, then desaturate, and lower the contrast &amp; brightness.</i> <br/>   Finally, it is sad, but none of what I just told you would have qualified for this challenge (since my suggestions are more for an Advanced Editting challenge,) but if you are just wanting to improve your digital technique/post-process skills (like I do,) then I believe that these are things that will help your portfolio &amp; would be desired from anyone (pretty much the way I have been helped by DPC.)<br/>    My comments aren''t the most expert here, but I hope that they will prove to be a "diving board" for progress.   :)</td>', 'My eye seems to be equally drawn to the well-focused trees as much as the RR tracks.  I do like your creative efforts compositionally, and the tracks are acceptably well-focused, even though the tree limb seems to be the point of your camera''s auto-focus sensor.  A simple, but effective near-instant improvement IMHO would be to select the bottom half (just below the needles) in even a simple editting program, like Broderbund''s Print Shop 15 (or Classic.)  Then, increase contrast & brightness on the selected.  Follow-up with select inverse, then desaturate, and lower the contrast & brightness.    Finally, it is sad, but none of what I just told you would have qualified for this challenge (since my suggestions are more for an Advanced Editting challenge,) but if you are just wanting to improve your digital technique/post-process skills (like I do,) then I believe that these are things that will help your portfolio & would be desired from anyone (pretty much the way I have been helped by DPC.)    My comments aren''t the most expert here, but I hope that they will prove to be a "diving board" for progress.   :)', '2006-10-26 10:23:13.000000', NULL, 1),
(2964702, 415446, 50034, '<td valign="top"><b>Got Confidence?</b> <i>Got Sky!  Got Tracks!  Got Photo!  Got Composition!  Got My Interest!  Got Hyperfocal Distance!</i> <u>Got Homage to Ansel Adams (in B/W!)</u> <b>Got Camera!  Got Skills!</b>   You Go!</td>', 'Got Confidence? Got Sky!  Got Tracks!  Got Photo!  Got Composition!  Got My Interest!  Got Hyperfocal Distance! Got Homage to Ansel Adams (in B/W!) Got Camera!  Got Skills!   You Go!', '2006-10-26 10:37:37.000000', NULL, 1),
(2964703, 415145, 50034, '<td valign="top">"Trained eye!  Nice!  :)</td>', '"Trained eye!  Nice!  :)', '2006-10-26 10:38:21.000000', NULL, 1),
(2964727, 414552, 50034, '<td valign="top">This is a beautiful photo as to vibrant colors &amp; fine composition!  However, IMHO this is a bit <b>rococo</b> (i.e. <i>Too Complex/Too Ornate</i>) for over-all positive effect.  I picked up a Rule of Thumb that seems to help me.  Hope it will help you as well...<b>"The difference between Monet and ''an amateur with a paint brush'' is often <i>Just One Stoke...More</i>."</b>   Finally, I hope I can subtract a little "sting" by saying that there are <i>many fine photographic qualities in this picture and an apparent passion for photography in you.</i> <b>Please be encouraged that you have a promising future!</b><br/><br/><i>Message edited by author 2006-11-03 02:09:57.</i></td>', 'This is a beautiful photo as to vibrant colors & fine composition!  However, IMHO this is a bit rococo (i.e. Too Complex/Too Ornate) for over-all positive effect.  I picked up a Rule of Thumb that seems to help me.  Hope it will help you as well..."The difference between Monet and ''an amateur with a paint brush'' is often Just One Stoke...More."   Finally, I hope I can subtract a little "sting" by saying that there are many fine photographic qualities in this picture and an apparent passion for photography in you. Please be encouraged that you have a promising future!', '2006-10-26 10:52:48.000000', '2006-11-03 02:09:57.000000', 1),
(2964746, 414213, 50034, '<td valign="top">Interesting Career Path for this young man.   Proverbs 22:6, <i>"<b>TRAIN</b> up a child in the way he should go, and when he is old he will not depart from it."</i> <b>"Woooooo-A-Wooooo, Mom!"</b></td>', 'Interesting Career Path for this young man.   Proverbs 22:6, "TRAIN up a child in the way he should go, and when he is old he will not depart from it." "Woooooo-A-Wooooo, Mom!"', '2006-10-26 10:58:44.000000', NULL, 1),
(2964756, 415198, 50034, '<td valign="top">Nice photo!  Pretty model!  I can "feel" the mood!  Kudos!  Mission Accomplished!  :)</td>', 'Nice photo!  Pretty model!  I can "feel" the mood!  Kudos!  Mission Accomplished!  :)', '2006-10-26 11:02:11.000000', NULL, 1),
(2964768, 414307, 50034, '<td valign="top">Nice wide-angle photo, glow in BG, and muted colors to give the "feel" of a mechanics work station.  Nice job!</td>', 'Nice wide-angle photo, glow in BG, and muted colors to give the "feel" of a mechanics work station.  Nice job!', '2006-10-26 11:04:59.000000', NULL, 1),
(2964771, 414623, 50034, '<td valign="top">Nice DOF!</td>', 'Nice DOF!', '2006-10-26 11:05:41.000000', NULL, 1),
(2964776, 415049, 50034, '<td valign="top">Nice "Postcard" photo!  You know...at this distance...it almost appears to be a miniature train on someone''s game room table...and...if it was it could pass for the cover photo of a Thomas, The Train episode.   :)</td>', 'Nice "Postcard" photo!  You know...at this distance...it almost appears to be a miniature train on someone''s game room table...and...if it was it could pass for the cover photo of a Thomas, The Train episode.   :)', '2006-10-26 11:10:00.000000', NULL, 1),
(2964777, 415212, 50034, '<td valign="top">How True!  :)</td>', 'How True!  :)', '2006-10-26 11:10:57.000000', NULL, 1),
(2964781, 414485, 50034, '<td valign="top">Nice little "off-track" locomotive you''re advertising there!  ;)</td>', 'Nice little "off-track" locomotive you''re advertising there!  ;)', '2006-10-26 11:12:34.000000', NULL, 1),
(2964785, 415437, 50034, '<td valign="top">Agreed!   However, IMHO the brightness could be less for more punch!  Yet, if you were going for that ancient, fading, deteriorating photo "feel", then...you NAILED it!  :)</td>', 'Agreed!   However, IMHO the brightness could be less for more punch!  Yet, if you were going for that ancient, fading, deteriorating photo "feel", then...you NAILED it!  :)', '2006-10-26 11:16:26.000000', NULL, 1),
(2964787, 415587, 50034, '<td valign="top">Interesting take/composition!  I''ll take it!  Nice!  :)</td>', 'Interesting take/composition!  I''ll take it!  Nice!  :)', '2006-10-26 11:18:06.000000', NULL, 1),
(2964916, 415665, 53316, '<td valign="top">*falls over from the awesome*<br/> <br/>Wow.  Just...... WOW.<br/>One of the most gorgeous images I''ve seen.</td>', '*falls over from the awesome* Wow.  Just...... WOW.One of the most gorgeous images I''ve seen.', '2006-10-26 12:26:00.000000', NULL, 1),
(2964932, 415193, 53316, '<td valign="top">Definitely taking advantage of the maximum allowed filesize (150k) would help in the future, to avoid the pixelated look.<br/> <br/>I like the composition and concept of this shot.</td>', 'Definitely taking advantage of the maximum allowed filesize (150k) would help in the future, to avoid the pixelated look. I like the composition and concept of this shot.', '2006-10-26 12:31:02.000000', NULL, 1),
(2965095, 414681, 40718, '<td valign="top">You got some halos, but I really like this shot. 9</td>', 'You got some halos, but I really like this shot. 9', '2006-10-26 13:36:00.000000', NULL, 1),
(2965096, 414404, 40718, '<td valign="top">I''m giving a bonus point for all toy trains. 7</td>', 'I''m giving a bonus point for all toy trains. 7', '2006-10-26 13:37:36.000000', NULL, 1),
(2965099, 415186, 40718, '<td valign="top">ooh, could have been awesome, but the PP is a bit rough. 6</td>', 'ooh, could have been awesome, but the PP is a bit rough. 6', '2006-10-26 13:38:16.000000', NULL, 1),
(2965376, 414204, 53316, '<td valign="top">DOF is too extreme for my tastes but I like the composition.</td>', 'DOF is too extreme for my tastes but I like the composition.', '2006-10-26 15:53:56.000000', NULL, 1),
(2965380, 414783, 53316, '<td valign="top">Composition feels a little off to me - would have liked to see either less black space or the entire curve.  But I really like this idea, as well as the colors of the shot.</td>', 'Composition feels a little off to me - would have liked to see either less black space or the entire curve.  But I really like this idea, as well as the colors of the shot.', '2006-10-26 15:55:18.000000', NULL, 1),
