(2967676, 415244, 65234, '<td valign="top">Looks grainy, though that may be the texture of the toy.  Not sure the B&amp;W made this more interesting.</td>', 'Looks grainy, though that may be the texture of the toy.  Not sure the B&W made this more interesting.', '2006-10-27 10:35:51.000000', NULL, 1),
(2967679, 414450, 65234, '<td valign="top">Interesting perspective; might be better with that white building on the left cloned out and a bit more saturated colors.</td>', 'Interesting perspective; might be better with that white building on the left cloned out and a bit more saturated colors.', '2006-10-27 10:37:17.000000', NULL, 1),
(2967682, 415670, 65234, '<td valign="top">They don''t look too thrilled at posing ;-)  Awfully clean train!</td>', 'They don''t look too thrilled at posing ;-)  Awfully clean train!', '2006-10-27 10:38:17.000000', NULL, 1),
