INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2967779, 414485, 65234, '<td valign="top">Would make a nice car ad ...</td>', 'Would make a nice car ad ...', '2006-10-27 11:09:49.000000', NULL, 1),
(2967784, 414177, 65234, '<td valign="top">Conveys OOF more strongly than a sense of movement.</td>', 'Conveys OOF more strongly than a sense of movement.', '2006-10-27 11:10:40.000000', NULL, 1),
(2967794, 415233, 65234, '<td valign="top">Would be better as an image without the train tracks.</td>', 'Would be better as an image without the train tracks.', '2006-10-27 11:12:06.000000', NULL, 1),
(2967800, 414590, 65234, '<td valign="top">Points for humor ;-)</td>', 'Points for humor ;-)', '2006-10-27 11:13:14.000000', NULL, 1),
(2967804, 414213, 65234, '<td valign="top">Well-titled ;-)</td>', 'Well-titled ;-)', '2006-10-27 11:13:34.000000', NULL, 1),
(2967817, 415113, 65234, '<td valign="top">Love the title with the ghostly train :-)  A bit cluttered as an image.</td>', 'Love the title with the ghostly train :-)  A bit cluttered as an image.', '2006-10-27 11:15:42.000000', NULL, 1),
(2967824, 415471, 65234, '<td valign="top">The signal is a bit OOF.</td>', 'The signal is a bit OOF.', '2006-10-27 11:16:22.000000', NULL, 1),
(2967835, 415049, 65234, '<td valign="top">Pretty composition.  Would''ve liked a little ore detail on the train engine.</td>', 'Pretty composition.  Would''ve liked a little ore detail on the train engine.', '2006-10-27 11:18:42.000000', NULL, 1),
(2967844, 414204, 65234, '<td valign="top">The sharpest focus appears to be a rock and a bit of weed.</td>', 'The sharpest focus appears to be a rock and a bit of weed.', '2006-10-27 11:19:36.000000', NULL, 1),
(2967848, 415436, 65234, '<td valign="top">Very cool perspective!</td>', 'Very cool perspective!', '2006-10-27 11:19:43.000000', NULL, 1),
(2967855, 415190, 65234, '<td valign="top">Lovely scene; might like the train a little brighter.</td>', 'Lovely scene; might like the train a little brighter.', '2006-10-27 11:21:02.000000', NULL, 1),
(2967940, 414603, 66418, '<td valign="top">Lighting is captivating</td>', 'Lighting is captivating', '2006-10-27 11:47:12.000000', NULL, 1),
(2967962, 415246, 50695, '<td valign="top">There were a lot of good photos in this challenge, but I reserved my 10s for photos that were unique and surprising. This is one of them. What a glorious, almost nonsensical jumble of wheels and armor! And is that an iron hand? It''s probably just being hosed down, but the effect is one of a magical chariot journeying through a rainy wonderland. 10</td>', 'There were a lot of good photos in this challenge, but I reserved my 10s for photos that were unique and surprising. This is one of them. What a glorious, almost nonsensical jumble of wheels and armor! And is that an iron hand? It''s probably just being hosed down, but the effect is one of a magical chariot journeying through a rainy wonderland. 10', '2006-10-27 12:01:15.000000', NULL, 1),
(2967968, 415113, 50695, '<td valign="top">This effect was done elsewhere in the challenge, but nowhere integrated so beautifully as this. Colorful, exciting, transformational. 10</td>', 'This effect was done elsewhere in the challenge, but nowhere integrated so beautifully as this. Colorful, exciting, transformational. 10', '2006-10-27 12:02:11.000000', NULL, 1),
(2967971, 415477, 50695, '<td valign="top">This photo just blows me away. When I think about it analytically, I say "big deal, he''s just ponting a camera at some girders," but when I look at it, I feel like I''m falling, or rising, or is that spinning? An incredible visceral effect. That''s the reaction that matters. The rest is just horsehocky. 10</td>', 'This photo just blows me away. When I think about it analytically, I say "big deal, he''s just ponting a camera at some girders," but when I look at it, I feel like I''m falling, or rising, or is that spinning? An incredible visceral effect. That''s the reaction that matters. The rest is just horsehocky. 10', '2006-10-27 12:03:53.000000', NULL, 1),
(2967974, 415340, 50695, '<td valign="top">This is so expressive. It is Picasso''s traffic light. I wonder if there''s any way to salvage the beautify of this while letting it be in color? Or maybe it works so well because we are left to imagine the colors. 10</td>', 'This is so expressive. It is Picasso''s traffic light. I wonder if there''s any way to salvage the beautify of this while letting it be in color? Or maybe it works so well because we are left to imagine the colors. 10', '2006-10-27 12:05:39.000000', NULL, 1),
(2967978, 415651, 50695, '<td valign="top">I love the subtlety of this morion blur. The train seems otherworldly, almost glowing like it''s about to flash out of existence. 9</td>', 'I love the subtlety of this morion blur. The train seems otherworldly, almost glowing like it''s about to flash out of existence. 9', '2006-10-27 12:06:45.000000', NULL, 1),
(2967984, 415192, 50695, '<td valign="top">Gritty exciting composition, a dynamic jumble of shapes, a mix of fine detail/highlights with bold simple shapes. 9</td>', 'Gritty exciting composition, a dynamic jumble of shapes, a mix of fine detail/highlights with bold simple shapes. 9', '2006-10-27 12:08:02.000000', NULL, 1),
(2967985, 415525, 50695, '<td valign="top">They seem so alive, like snakes in their den. There''s a timeless quality to this. 9</td>', 'They seem so alive, like snakes in their den. There''s a timeless quality to this. 9', '2006-10-27 12:09:13.000000', NULL, 1),
(2967987, 415611, 24073, '<td valign="top">Lacking that depth of field focus.  Not the Bokeh, I like that, but the focus at the upper part of her body.  I really like the composition, and I like the tones, mood, and the unique idea, hopefully it fairs well because I like it alot, but I could almost guarantee you would of earned a top 10 spot if the focus was just a smidgin more clear.  GL.</td>', 'Lacking that depth of field focus.  Not the Bokeh, I like that, but the focus at the upper part of her body.  I really like the composition, and I like the tones, mood, and the unique idea, hopefully it fairs well because I like it alot, but I could almost guarantee you would of earned a top 10 spot if the focus was just a smidgin more clear.  GL.', '2006-10-27 12:09:45.000000', NULL, 1),
(2967990, 415168, 50695, '<td valign="top">brilliant stroke to "remove" the slats from the tracks and just create two bolts of lightning entering darkness. a bold stroke to devote so much of your composition to it. 10</td>', 'brilliant stroke to "remove" the slats from the tracks and just create two bolts of lightning entering darkness. a bold stroke to devote so much of your composition to it. 10', '2006-10-27 12:10:33.000000', NULL, 1),
(2967991, 415629, 50695, '<td valign="top">Great use of color. I love the relationship between man and machine. That fellow in the middle seems to be holding the whole world together. 10</td>', 'Great use of color. I love the relationship between man and machine. That fellow in the middle seems to be holding the whole world together. 10', '2006-10-27 12:11:25.000000', NULL, 1),
(2967995, 413049, 50695, '<td valign="top">very nice oldee tymee processing; lovely, elegant composition. There''s something haunting about this picture. 9</td>', 'very nice oldee tymee processing; lovely, elegant composition. There''s something haunting about this picture. 9', '2006-10-27 12:12:30.000000', NULL, 1),
(2967997, 415533, 50695, '<td valign="top">Very creative to shoot the station instead of the train! This is the Relativity Interpretation. The train''s not moving, the world is! 9</td>', 'Very creative to shoot the station instead of the train! This is the Relativity Interpretation. The train''s not moving, the world is! 9', '2006-10-27 12:13:32.000000', NULL, 1),
(2967998, 413838, 50695, '<td valign="top">I love how the world behind it is faded almost completely away. This looks like many other shots in the challenge, but yours has a magic that they lack. 8</td>', 'I love how the world behind it is faded almost completely away. This looks like many other shots in the challenge, but yours has a magic that they lack. 8', '2006-10-27 12:14:27.000000', NULL, 1),
(2968000, 415470, 50695, '<td valign="top">Good, exciting chiaroscuro candid of what for them is a mundane moment. 8</td>', 'Good, exciting chiaroscuro candid of what for them is a mundane moment. 8', '2006-10-27 12:15:22.000000', NULL, 1),
(2968003, 415092, 50695, '<td valign="top">I love photos that depend so much on composition. They become almost pure photographs. 9</td>', 'I love photos that depend so much on composition. They become almost pure photographs. 9', '2006-10-27 12:16:12.000000', NULL, 1),
(2968007, 415117, 50695, '<td valign="top">I love the two worlds, divided down the middle. 7</td>', 'I love the two worlds, divided down the middle. 7', '2006-10-27 12:16:44.000000', NULL, 1),
(2968016, 415443, 24073, '<td valign="top">beautiful composition.  OK Im back, Im bumpin this one up a couple notches.  It amazes me how well you composed something so simple.  Not to mention, I cant even imagine how you got the depth focus so clear.  I''m betting, a really expensive lens.  LOL.  GL.</td>', 'beautiful composition.  OK Im back, Im bumpin this one up a couple notches.  It amazes me how well you composed something so simple.  Not to mention, I cant even imagine how you got the depth focus so clear.  I''m betting, a really expensive lens.  LOL.  GL.', '2006-10-27 12:19:09.000000', NULL, 1),
(2968023, 414677, 24073, '<td valign="top">This is a brilliant photo, and I don''t want to take anything from it, but do you sort of feel off balanced somehow?  I like it, and voted high, but each time I look at it something seems just a little off, I dunno maybe the lights.  Owe yeah the way you exposed those lights is super cool.</td>', 'This is a brilliant photo, and I don''t want to take anything from it, but do you sort of feel off balanced somehow?  I like it, and voted high, but each time I look at it something seems just a little off, I dunno maybe the lights.  Owe yeah the way you exposed those lights is super cool.', '2006-10-27 12:22:09.000000', NULL, 1),
(2968040, 415321, 24073, '<td valign="top">Its going to be really hard for anybody to say you didn''t nail this one perfectly.  I''ll tell you what, I never cared too much for trains, but your photo makes me want to start collecting, starting with your photo.  LOL.  I''m not an incredibly accurate judge, but I got you as 2nd on my scorecard.  GL, I think you will do very well.</td>', 'Its going to be really hard for anybody to say you didn''t nail this one perfectly.  I''ll tell you what, I never cared too much for trains, but your photo makes me want to start collecting, starting with your photo.  LOL.  I''m not an incredibly accurate judge, but I got you as 2nd on my scorecard.  GL, I think you will do very well.', '2006-10-27 12:30:27.000000', NULL, 1),
(2968043, 414681, 24073, '<td valign="top">This is just a downright good photo of a train yard.  Your choices in creating this photo were awesome.  The tones, the mood, and the comp. are wonderful.  I''ll be rootin for you.  GL.</td>', 'This is just a downright good photo of a train yard.  Your choices in creating this photo were awesome.  The tones, the mood, and the comp. are wonderful.  I''ll be rootin for you.  GL.', '2006-10-27 12:32:06.000000', NULL, 1),
(2968044, 415198, 24073, '<td valign="top">Composed beautifully, looks very professional.  Her colors (awesome), the train colors (splendid), the sky (perfect).  I think I would of pulled the lollipop thingy out of the ground, but it doesn''t hurt the photo just personal preference.  Owe yeah border was an awesome choice as well.  Bumping this one up from 7 to 9.</td>', 'Composed beautifully, looks very professional.  Her colors (awesome), the train colors (splendid), the sky (perfect).  I think I would of pulled the lollipop thingy out of the ground, but it doesn''t hurt the photo just personal preference.  Owe yeah border was an awesome choice as well.  Bumping this one up from 7 to 9.', '2006-10-27 12:32:51.000000', NULL, 1),
(2968074, 415153, 24073, '<td valign="top">At first glance I wasn''t incredibly impressed with this photo, but all week I have been steadily bumping it up till now it is in my top 10.  I just wanted to say sincerely that this is an incredible photo.</td>', 'At first glance I wasn''t incredibly impressed with this photo, but all week I have been steadily bumping it up till now it is in my top 10.  I just wanted to say sincerely that this is an incredible photo.', '2006-10-27 12:42:32.000000', NULL, 1),
(2968080, 415519, 65234, '<td valign="top">Very nice shot!</td>', 'Very nice shot!', '2006-10-27 12:44:06.000000', NULL, 1),
(2968082, 415537, 24073, '<td valign="top">Alright so you nailed it, and by now I''ll bet you know it.  Just wanted to say great job in capturing a truly magnificent shot.</td>', 'Alright so you nailed it, and by now I''ll bet you know it.  Just wanted to say great job in capturing a truly magnificent shot.', '2006-10-27 12:44:15.000000', NULL, 1),
(2968086, 415604, 30637, '<td valign="top">And where is Jones?</td>', 'And where is Jones?', '2006-10-27 12:44:51.000000', NULL, 1),
(2968094, 415533, 24073, '<td valign="top">Alright I don''t know how this will fair amongst the other voters, but you got mine.  Great abstract, and great vision, it came out awesome.  Must of been pretty freaky standing there though. LOL.  GL.</td>', 'Alright I don''t know how this will fair amongst the other voters, but you got mine.  Great abstract, and great vision, it came out awesome.  Must of been pretty freaky standing there though. LOL.  GL.', '2006-10-27 12:46:14.000000', NULL, 1),
