(2971602, 415658, 30896, '<td valign="top">I like the simplicity, but i am a bit puzzled by the perspective here :-)<br/> <br/>edit to explain myself:<br/>the rails on the top of the picture get suddenly very thin and sideways, unlike the usual rails I know, <br/><br/><br/><i>Message edited by author 2006-11-30 18:25:26.</i></td>', 'I like the simplicity, but i am a bit puzzled by the perspective here :-) edit to explain myself:the rails on the top of the picture get suddenly very thin and sideways, unlike the usual rails I know, ', '2006-10-28 22:23:54.000000', '2006-11-30 18:25:26.000000', 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2971647, 414318, 34396, '<td valign="top">I like the angle of this shot.  The deep blue sky is a nice contrast to the yellow engine.  The right side of the train and sky seem a slight bit blown out.</td>', 'I like the angle of this shot.  The deep blue sky is a nice contrast to the yellow engine.  The right side of the train and sky seem a slight bit blown out.', '2006-10-28 22:32:56.000000', NULL, 1),
(2971718, 414420, 48541, '<td valign="top">i don''t know where these tracks lead but it looks magical. thumbs up.</td>', 'i don''t know where these tracks lead but it looks magical. thumbs up.', '2006-10-28 22:49:24.000000', NULL, 1),
(2971720, 415519, 48541, '<td valign="top">Good shot. I feel like the person on the bridge is waiving at me.  I actually raised my hand and waived back.  Awkward but true. Thumbs up.</td>', 'Good shot. I feel like the person on the bridge is waiving at me.  I actually raised my hand and waived back.  Awkward but true. Thumbs up.', '2006-10-28 22:51:10.000000', NULL, 1),
(2971744, 413838, 60566, '<td valign="top">10x 1000</td>', '10x 1000', '2006-10-28 23:01:14.000000', NULL, 1),
(2971748, 413454, 67698, '<td valign="top">Cute kid! More importantly, I think the shot is well composed. The girl is not interfering with the tracks, which really draw your eyes deeper into the shot, without letting go.</td>', 'Cute kid! More importantly, I think the shot is well composed. The girl is not interfering with the tracks, which really draw your eyes deeper into the shot, without letting go.', '2006-10-28 23:02:36.000000', NULL, 1),
(2971751, 415504, 67698, '<td valign="top">I can''t say that my eyes want to stay in this picture... The straight line of the train draws my eyes along and away, to the next picture. It could have been better composed.</td>', 'I can''t say that my eyes want to stay in this picture... The straight line of the train draws my eyes along and away, to the next picture. It could have been better composed.', '2006-10-28 23:04:09.000000', NULL, 1),
(2971762, 415437, 67698, '<td valign="top">You were going for an "old timey" feel with the sepia tones, but it looks more than a bit washed out. Its also a cool looking train, and the shot exudes traininess - can''t get trainer than a train - but the head-on composition just doesn''t do it for me.</td>', 'You were going for an "old timey" feel with the sepia tones, but it looks more than a bit washed out. Its also a cool looking train, and the shot exudes traininess - can''t get trainer than a train - but the head-on composition just doesn''t do it for me.', '2006-10-28 23:07:11.000000', NULL, 1),
(2971766, 415109, 67698, '<td valign="top">I really like the colors and composition in this shot. Both just seem to "pop".</td>', 'I really like the colors and composition in this shot. Both just seem to "pop".', '2006-10-28 23:09:36.000000', NULL, 1),
(2971770, 415370, 67698, '<td valign="top">Maybe its just me, but I get a distinct "retro-futuristic" feel in this shot.. On the one hand you''ve got a cool modern bullet train, and on the other there is a black-and-white almost "silent movie"-ish look to the passengers.</td>', 'Maybe its just me, but I get a distinct "retro-futuristic" feel in this shot.. On the one hand you''ve got a cool modern bullet train, and on the other there is a black-and-white almost "silent movie"-ish look to the passengers.', '2006-10-28 23:11:42.000000', NULL, 1),
(2971776, 415519, 67698, '<td valign="top">Beautiful colors. I love the silhouette of the person stands out against the sky. The picture really draws my eyes deeper and deeper. Nice!</td>', 'Beautiful colors. I love the silhouette of the person stands out against the sky. The picture really draws my eyes deeper and deeper. Nice!', '2006-10-28 23:15:30.000000', NULL, 1),
(2971783, 415508, 67698, '<td valign="top">I like the composition in this shot. It really feels like I''m there. The man looks like he belongs there (and probably does!). The tracks lead my eyes deeper into the shot and not away from it. Nice!</td>', 'I like the composition in this shot. It really feels like I''m there. The man looks like he belongs there (and probably does!). The tracks lead my eyes deeper into the shot and not away from it. Nice!', '2006-10-28 23:18:48.000000', NULL, 1),
(2971785, 415611, 67698, '<td valign="top">Wow, its an emotional shot. I would have probably not cropped off the right-hand rail, and left the girl more on the left side of the shot instead, but I suppose it would have been a different shot then, with a different feeling.</td>', 'Wow, its an emotional shot. I would have probably not cropped off the right-hand rail, and left the girl more on the left side of the shot instead, but I suppose it would have been a different shot then, with a different feeling.', '2006-10-28 23:21:11.000000', NULL, 1),
(2971793, 415277, 67698, '<td valign="top">I assume the man is the focus of this shot, but I had trouble finding him to begin with. It doesn''t seem to give him enough of a presence to justify the title.</td>', 'I assume the man is the focus of this shot, but I had trouble finding him to begin with. It doesn''t seem to give him enough of a presence to justify the title.', '2006-10-28 23:23:47.000000', NULL, 1),
(2971796, 414603, 67698, '<td valign="top">I like the way the steam mists up the shot. It feels exceptionally trainy.</td>', 'I like the way the steam mists up the shot. It feels exceptionally trainy.', '2006-10-28 23:25:33.000000', NULL, 1),
(2971804, 415198, 67698, '<td valign="top">A pretty face is a stark contract on the rusted backdrop. I really like the colors in this shot. Its a foreboding sort of place!</td>', 'A pretty face is a stark contract on the rusted backdrop. I really like the colors in this shot. Its a foreboding sort of place!', '2006-10-28 23:27:29.000000', NULL, 1),
(2971807, 414643, 67698, '<td valign="top">Feels like city is quite a blur, with time slipping by unnoticed.. I like the night-time colors in this shot, as well as the framing.</td>', 'Feels like city is quite a blur, with time slipping by unnoticed.. I like the night-time colors in this shot, as well as the framing.', '2006-10-28 23:29:06.000000', NULL, 1),
(2971811, 414552, 10818, '<td valign="top">Wonderful contrast with the vivid yellow and red leaves.  Interesting old bridge and nice composition.</td>', 'Wonderful contrast with the vivid yellow and red leaves.  Interesting old bridge and nice composition.', '2006-10-28 23:30:05.000000', NULL, 1),
(2971823, 415504, 34396, '<td valign="top">I think the lighting could have been a bit better in this photo.  Also, try to use the full 640 pixels for your photo as this small photo is somewhat hard to critique.</td>', 'I think the lighting could have been a bit better in this photo.  Also, try to use the full 640 pixels for your photo as this small photo is somewhat hard to critique.', '2006-10-28 23:35:06.000000', NULL, 1),
