(2971921, 415220, 42495, '<td valign="top">Nice capture of the feel of the area; would be nice to have the train more prominent.</td>', 'Nice capture of the feel of the area; would be nice to have the train more prominent.', '2006-10-29 00:21:07.000000', NULL, 1),
(2971941, 414223, 34618, '<td valign="top">Looks hand-held and, assuming that was the intention, the blurring is distracting. Not sure what you were going for. Had it been shot from a tripod, I think it would have been much stronger due to the good overall exposure and vividness of the greens, backlight on the tree and reflections off the rails.</td>', 'Looks hand-held and, assuming that was the intention, the blurring is distracting. Not sure what you were going for. Had it been shot from a tripod, I think it would have been much stronger due to the good overall exposure and vividness of the greens, backlight on the tree and reflections off the rails.', '2006-10-29 00:30:37.000000', NULL, 1),
(2971944, 415212, 34618, '<td valign="top">Nice idea but the overall effect seems too intense.</td>', 'Nice idea but the overall effect seems too intense.', '2006-10-29 00:32:13.000000', NULL, 1),
