(3020086, 414623, 64209, '<td valign="top">Congratulations!</td>', 'Congratulations!', '2006-11-10 12:25:28.000000', NULL, 0),
(3021630, 414318, 55838, '<td valign="top">Fine complimentary colors here.  Cool perspective on the train.  The sky has such a lovely blue that my eyes would like to see a bit more of it in the pick.  Looks like you had challenging lighting conditions that left you a little bit of bright blow-out and then shadows on the front of the train.  IMO a little tighter focus and maybe a little more crop off the bottom might have improved the shot a bit.</td>', 'Fine complimentary colors here.  Cool perspective on the train.  The sky has such a lovely blue that my eyes would like to see a bit more of it in the pick.  Looks like you had challenging lighting conditions that left you a little bit of bright blow-out and then shadows on the front of the train.  IMO a little tighter focus and maybe a little more crop off the bottom might have improved the shot a bit.', '2006-11-11 08:41:07.000000', NULL, 0),
(3021945, 414423, 66384, '<td valign="top">Clever use of the blur and smudge. I wondered how you did this. I learned something here.</td>', 'Clever use of the blur and smudge. I wondered how you did this. I learned something here.', '2006-11-11 13:57:44.000000', NULL, 0),
(3021976, 415277, 66384, '<td valign="top">I think I would try to bring a little more life into the buildings in the background. I don''t mind the man in the foreground, but from a scoring point of view, I think you made a mistake pointing him out. You have a bright, vibrant focus on the lower left quadrant. I''d like to see more of that in the train station, which is quite interesting.</td>', 'I think I would try to bring a little more life into the buildings in the background. I don''t mind the man in the foreground, but from a scoring point of view, I think you made a mistake pointing him out. You have a bright, vibrant focus on the lower left quadrant. I''d like to see more of that in the train station, which is quite interesting.', '2006-11-11 14:18:42.000000', NULL, 0),
(3031210, 415665, 24613, '<td valign="top">I really like the colors here.  This is a GREAT shot!</td>', 'I really like the colors here.  This is a GREAT shot!', '2006-11-14 17:54:09.000000', NULL, 0),
